def transform(grid):
    from collections import Counter
    g = np.array(grid)
    bg = background(g)
    def runs(mask):
        res, start = [], None
        for i, v in enumerate(mask):
            if v and start is None:
                start = i
            if not v and start is not None:
                res.append((start, i - 1)); start = None
        if start is not None:
            res.append((start, len(mask) - 1))
        return res
    rows = runs([(g[y] != bg).any() for y in range(g.shape[0])])
    cols = runs([(g[:, x] != bg).any() for x in range(g.shape[1])])
    out = np.full((len(rows) + 2, len(cols) + 2), bg, dtype=int)
    emit(out, "Allocate a background canvas with one cell per tile plus a 1-cell border.")
    for r, (y0, y1) in enumerate(rows):
        for c, (x0, x1) in enumerate(cols):
            vals = [v for v in g[y0:y1 + 1, x0:x1 + 1].ravel() if v != bg]
            if vals:
                out[1 + r, 1 + c] = Counter(vals).most_common(1)[0][0]
        emit(out, f"Tile row {r}: each tile is replaced by its majority colour.")
    emit(out, "Final grid: majority colour of every tile, framed by background.")
    return out
